-- Ejecutar en Supabase -> SQL Editor -> New query -> Run.
-- Requiere 01_esquema.sql.
--
-- Armas de Genshin Impact: 246. Con stats, efecto por nivel, como
-- conseguirlas, materiales y personajes recomendados (guias de Game8).
--
-- Los datos son una copia de la base de datos tal y como estaba el 2026-09-15.
-- Inserta lo que falte y actualiza lo que ya exista, sin borrar nada: los
-- favoritos, tier lists y guias de los usuarios que apuntan a estas filas se
-- conservan. Ojo: si has cambiado algo desde la app despues de esa fecha,
-- ejecutarlo lo devuelve a como estaba en la copia.
--
-- Estas armas no estaban en la copia de la base de datos (genshin_armas.sql no
-- llego a ejecutarse), asi que salen de los archivos: datos de Yatta y
-- recomendados de Game8.

--
-- PARTE 3 de 4 (66 filas). El archivo entero no cabia en el SQL Editor:
-- ejecuta las 4 partes, en cualquier orden.

insert into public.weapons (
  id, game_id, name, name_en, rarity, category, image_url, description, base_hp, base_atk, base_def, sub_stat_name, sub_stat_value, passive_name, passive_levels, how_to_get, ascension, good_for, recommended
)
values
  ('gi-w-14516', 'genshin-impact', 'Hora de Surfear', 'Surf''s Up', '5', 'Catalizador', 'https://gi.yatta.moe/assets/UI/UI_EquipIcon_Catalyst_MechaPufferfish.png', 'Un objeto conmemorativo que, supuestamente, se le iba a entregar al ganador de la primera edición del Campeonato de Surf Intertribal. Como el torneo aún está en fase de preparación, el premio lo está guardando temporalmente la dueña de la tienda Peciglobos Parsimoniosos.', null, 542, null, 'Daño CRIT', '88,2%', 'Recuerdos del agua', '["La Vida Máx. aumenta en un 20%. Una vez cada 15 s, otorga los siguientes efectos durante 14 s después de usar la Habilidad Elemental: otorga 4 cargas de “estío”. Cada carga aumenta en un 12% el daño del Ataque Normal. Mientras este efecto está activo, una vez cada 1.5 s, elimina 1 carga de estío tras golpear a un enemigo con un Ataque Normal, y otorga 1 carga tras causar una reacción de Vaporización contra un enemigo. El efecto de estío puede acumularse hasta 4 veces.","La Vida Máx. aumenta en un 25%. Una vez cada 15 s, otorga los siguientes efectos durante 14 s después de usar la Habilidad Elemental: otorga 4 cargas de “estío”. Cada carga aumenta en un 15% el daño del Ataque Normal. Mientras este efecto está activo, una vez cada 1.5 s, elimina 1 carga de estío tras golpear a un enemigo con un Ataque Normal, y otorga 1 carga tras causar una reacción de Vaporización contra un enemigo. El efecto de estío puede acumularse hasta 4 veces.","La Vida Máx. aumenta en un 30%. Una vez cada 15 s, otorga los siguientes efectos durante 14 s después de usar la Habilidad Elemental: otorga 4 cargas de “estío”. Cada carga aumenta en un 18% el daño del Ataque Normal. Mientras este efecto está activo, una vez cada 1.5 s, elimina 1 carga de estío tras golpear a un enemigo con un Ataque Normal, y otorga 1 carga tras causar una reacción de Vaporización contra un enemigo. El efecto de estío puede acumularse hasta 4 veces.","La Vida Máx. aumenta en un 35%. Una vez cada 15 s, otorga los siguientes efectos durante 14 s después de usar la Habilidad Elemental: otorga 4 cargas de “estío”. Cada carga aumenta en un 21% el daño del Ataque Normal. Mientras este efecto está activo, una vez cada 1.5 s, elimina 1 carga de estío tras golpear a un enemigo con un Ataque Normal, y otorga 1 carga tras causar una reacción de Vaporización contra un enemigo. El efecto de estío puede acumularse hasta 4 veces.","La Vida Máx. aumenta en un 40%. Una vez cada 15 s, otorga los siguientes efectos durante 14 s después de usar la Habilidad Elemental: otorga 4 cargas de “estío”. Cada carga aumenta en un 24% el daño del Ataque Normal. Mientras este efecto está activo, una vez cada 1.5 s, elimina 1 carga de estío tras golpear a un enemigo con un Ataque Normal, y otorga 1 carga tras causar una reacción de Vaporización contra un enemigo. El efecto de estío puede acumularse hasta 4 veces."]'::jsonb, 'Tirando en el banner de armas del evento, mientras sale destacada', '[{"desde":20,"hasta":40,"creditos":10000,"materiales":[{"nombre":"Colmillo joven","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112101.png","cantidad":3},{"nombre":"Fragmento de voluntad quebrantada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112107.png","cantidad":5},{"nombre":"Terror del corazón sacrificial ardiente","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114061.png","cantidad":5}]},{"desde":40,"hasta":50,"creditos":20000,"materiales":[{"nombre":"Colmillo joven","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112101.png","cantidad":12},{"nombre":"Fragmento de voluntad quebrantada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112107.png","cantidad":18},{"nombre":"Indecisión del corazón sacrificial ardiente","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114062.png","cantidad":5}]},{"desde":50,"hasta":60,"creditos":30000,"materiales":[{"nombre":"Colmillo veterano","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112102.png","cantidad":9},{"nombre":"Ídolo de voluntad manifiesta","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112108.png","cantidad":9},{"nombre":"Indecisión del corazón sacrificial ardiente","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114062.png","cantidad":9}]},{"desde":60,"hasta":70,"creditos":45000,"materiales":[{"nombre":"Colmillo veterano","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112102.png","cantidad":14},{"nombre":"Ídolo de voluntad manifiesta","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112108.png","cantidad":18},{"nombre":"Determinación del corazón sacrificial ardiente","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114063.png","cantidad":5}]},{"desde":70,"hasta":80,"creditos":55000,"materiales":[{"nombre":"Colmillo de tirano","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112103.png","cantidad":9},{"nombre":"Sello de voluntad patrullera","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112109.png","cantidad":14},{"nombre":"Determinación del corazón sacrificial ardiente","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114063.png","cantidad":9}]},{"desde":80,"hasta":90,"creditos":65000,"materiales":[{"nombre":"Colmillo de tirano","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112103.png","cantidad":18},{"nombre":"Sello de voluntad patrullera","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112109.png","cantidad":27},{"nombre":"Honor del corazón sacrificial ardiente","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114064.png","cantidad":6}]}]'::jsonb, 'Mualani.', '[{"id":"gi-mualani","grupo":"lista"}]'::jsonb),
  ('gi-w-11430', 'genshin-impact', 'Hueso Recio', 'Sturdy Bone', '4', 'Espada ligera', 'https://gi.yatta.moe/assets/UI/UI_EquipIcon_Sword_Umpakati.png', 'Una larga espada ósea que se ha vuelto más robusta con cada batalla en la que ha luchado. Dicen que se trataba del arma de confianza de la heroína Wanjiru.', null, 565, null, 'ATQ', '27,6%', 'Orgullo del trampero', '["El Coste de Aguante de esprintar o de otras habilidades que sustituyen a esprintar se reduce en un 15%. Además, al esprintar o usar una habilidad que lo sustituya, el daño del Ataque Normal aumenta en una cantidad equivalente al 16% del ATQ. Este efecto se anula tras activarse 18 veces o después de 7 s.","El Coste de Aguante de esprintar o de otras habilidades que sustituyen a esprintar se reduce en un 15%. Además, al esprintar o usar una habilidad que lo sustituya, el daño del Ataque Normal aumenta en una cantidad equivalente al 20% del ATQ. Este efecto se anula tras activarse 18 veces o después de 7 s.","El Coste de Aguante de esprintar o de otras habilidades que sustituyen a esprintar se reduce en un 15%. Además, al esprintar o usar una habilidad que lo sustituya, el daño del Ataque Normal aumenta en una cantidad equivalente al 24% del ATQ. Este efecto se anula tras activarse 18 veces o después de 7 s.","El Coste de Aguante de esprintar o de otras habilidades que sustituyen a esprintar se reduce en un 15%. Además, al esprintar o usar una habilidad que lo sustituya, el daño del Ataque Normal aumenta en una cantidad equivalente al 28% del ATQ. Este efecto se anula tras activarse 18 veces o después de 7 s.","El Coste de Aguante de esprintar o de otras habilidades que sustituyen a esprintar se reduce en un 15%. Además, al esprintar o usar una habilidad que lo sustituya, el daño del Ataque Normal aumenta en una cantidad equivalente al 32% del ATQ. Este efecto se anula tras activarse 18 veces o después de 7 s."]'::jsonb, 'Tirando en el banner de armas del evento, mientras sale destacada', '[{"desde":20,"