09.png","cantidad":9},{"nombre":"Determinación del corazón sacrificial ardiente","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114063.png","cantidad":6}]},{"desde":80,"hasta":90,"creditos":45000,"materiales":[{"nombre":"Silbato de oro del soldado sauriocoronado","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112106.png","cantidad":12},{"nombre":"Sello de voluntad patrullera","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112109.png","cantidad":18},{"nombre":"Honor del corazón sacrificial ardiente","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114064.png","cantidad":4}]}]'::jsonb, 'Kamisato Ayaka, Keqing y Kaeya.', '[{"id":"gi-ayaka","grupo":"lista"},{"id":"gi-keqing","grupo":"lista"},{"id":"gi-kaeya","grupo":"lista"}]'::jsonb),
  ('gi-w-11415', 'genshin-impact', 'Huso de Cinabrio', 'Cinnabar Spindle', '4', 'Espada ligera', 'https://gi.yatta.moe/assets/UI/UI_EquipIcon_Sword_Opus.png', 'Una espada forjada con materiales que no son de este mundo. El poder que contiene podría incluso resistir la corrupción de un veneno capaz de derribar a un poderoso dragón.', null, 454, null, 'DEF', '69,0%', 'Corazón inmaculado', '["El daño infligido por la Habilidad Elemental aumenta en una cantidad equivalente al 40% de la DEF. Este efecto solo puede activarse una vez cada 1.5 s y se anula 0.1 s después de que la Habilidad Elemental inflija daño.","El daño infligido por la Habilidad Elemental aumenta en una cantidad equivalente al 50% de la DEF. Este efecto solo puede activarse una vez cada 1.5 s y se anula 0.1 s después de que la Habilidad Elemental inflija daño.","El daño infligido por la Habilidad Elemental aumenta en una cantidad equivalente al 60% de la DEF. Este efecto solo puede activarse una vez cada 1.5 s y se anula 0.1 s después de que la Habilidad Elemental inflija daño.","El daño infligido por la Habilidad Elemental aumenta en una cantidad equivalente al 70% de la DEF. Este efecto solo puede activarse una vez cada 1.5 s y se anula 0.1 s después de que la Habilidad Elemental inflija daño.","El daño infligido por la Habilidad Elemental aumenta en una cantidad equivalente al 80% de la DEF. Este efecto solo puede activarse una vez cada 1.5 s y se anula 0.1 s después de que la Habilidad Elemental inflija daño."]'::jsonb, 'Recompensa del evento «Shadows Amidst Snowstorms»', '[{"desde":20,"hasta":40,"creditos":5000,"materiales":[{"nombre":"Máscara dañada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112005.png","cantidad":2},{"nombre":"Dispositivo del caos","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112023.png","cantidad":3},{"nombre":"Fragmento de azulejo de Decarabian","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114001.png","cantidad":3}]},{"desde":40,"hasta":50,"creditos":15000,"materiales":[{"nombre":"Máscara dañada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112005.png","cantidad":8},{"nombre":"Dispositivo del caos","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112023.png","cantidad":12},{"nombre":"Escombro de la ciudad de Decarabian","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114002.png","cantidad":3}]},{"desde":50,"hasta":60,"creditos":20000,"materiales":[{"nombre":"Máscara sucia","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112006.png","cantidad":6},{"nombre":"Circuito del caos","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112024.png","cantidad":6},{"nombre":"Escombro de la ciudad de Decarabian","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114002.png","cantidad":6}]},{"desde":60,"hasta":70,"creditos":30000,"materiales":[{"nombre":"Máscara sucia","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112006.png","cantidad":9},{"nombre":"Circuito del caos","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112024.png","cantidad":12},{"nombre":"Fragmento de epopeya de Decarabian","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114003.png","cantidad":3}]},{"desde":70,"hasta":80,"creditos":35000,"materiales":[{"nombre":"Máscara amenazante","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112007.png","cantidad":6},{"nombre":"Caldera del caos","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112025.png","cantidad":9},{"nombre":"Fragmento de epopeya de Decarabian","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114003.png","cantidad":6}]},{"desde":80,"hasta":90,"creditos":45000,"materiales":[{"nombre":"Máscara amenazante","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112007.png","cantidad":12},{"nombre":"Caldera del caos","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112025.png","cantidad":18},{"nombre":"Fragmento de sueño de Decarabian","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114004.png","cantidad":4}]}]'::jsonb, 'Xilonen, Chiori y Albedo.', '[{"id":"gi-xilonen","grupo":"lista"},{"id":"gi-chiori","grupo":"lista"},{"id":"gi-albedo","grupo":"lista"}]'::jsonb),
  ('gi-w-14424', 'genshin-impact', 'Jade Sacrificial', 'Sacrificial Jade', '4', 'Catalizador', 'https://gi.yatta.moe/assets/UI/UI_EquipIcon_Catalyst_Yue.png', 'Una antigua pieza de jade del color de unas aguas turquesas. Posiblemente sea un viejo objeto de ofrendas y sacrificios.', null, 454, null, 'Prob. CRIT', '36,8%', 'Jade fluctuante', '["Cuando el personaje está en tu equipo pero no en uso durante más de 5 s, su Vida Máx. aumenta en un 32% y su Maestría Elemental aumenta en 40 pts. Este efecto se anulará cuando el portador de esta arma entre en el campo de batalla y permanezca en él durante 10 s.","Cuando el personaje está en tu equipo pero no en uso durante más de 5 s, su Vida Máx. aumenta en un 40% y su Maestría Elemental aumenta en 50 pts. Este efecto se anulará cuando el portador de esta arma entre en el campo de batalla y permanezca en él durante 10 s.","Cuando el personaje está en tu equipo pero no en uso durante más de 5 s, su Vida Máx. aumenta en un 48% y su Maestría Elemental aumenta en 60 pts. Este efecto se anulará cuando el portador de esta arma entre en el campo de batalla y permanezca en él durante 10 s.","Cuando el personaje está en tu equipo pero no en uso durante más de 5 s, su Vida Máx. aumenta en un 56% y su Maestría Elemental aumenta en 70 pts. Este efecto se anulará cuando el portador de esta arma entre en el campo de batalla y permanezca en él durante 10 s.","Cuando el personaje está en tu equipo pero no en uso durante más de 5 s, su Vida Máx. aumenta en un 64% y su Maestría Elemental aumenta en 80 pts. Este efecto se anulará cuando el portador de esta arma entre en el campo de batalla y permanezca en él durante 10 s."]'::jsonb, 'Pase de batalla: se elige al llegar al nivel 30 del Himno Gnóstico', '[{"desde":20,"hasta":40,"creditos":5000,"materiales":[{"nombre":"Pergamino guía","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112008.png","cantidad":2},{"nombre":"Polen neblinoso","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112026.png","cantidad":3},{"nombre":"Arena brillante de Guyun","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114013.png","cantidad":3}]},{"desde":40,"hasta":50,"creditos":15000,"materiales":[{"nombre":"Pergamino guía","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112008.png","cantidad":8},{"nombre":"Polen neblinoso","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112026.png","cantidad":12},{"nombre":"Piedra reluciente de Guyun","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114014.png","cantidad":3}]},{"desde":50,"hasta":60,"creditos":20000,"materiales":[{"nombre":"Pergamino hechizado","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112009.png","cantidad":6},{"nombre":"Hierba neblinosa","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112027.png","cantidad":6},{"nombre":"Piedra reluciente de Guyun","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114014.png","cantidad":6}]},{"desde":60,"hasta":70,"creditos":30000,"materiales":[{"nombre":"Pergamino hechizado","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112009.png","cantidad":9},{"nombre":"Hierba neblinosa","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112027.png","cantidad":12},{"nombre":"Reliquia de Guyun","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114015.png","cantidad":3}]},{"desde":70,"hasta":80,"creditos":35000,"materiales":[{"nombre":"Pergamino maldito","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112010.png","cantidad":6},{"nombre":"Lámpara de hierba neblinosa","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112028.png","cantidad":9},{"nombre":"Reliquia de Guyun","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114015.png","cantidad":6}]},{"desde":80,"hasta":90,"creditos":45000,"materiales":[{"nombre":"Pergamino maldito","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112010.png","cantidad":12},{"nombre":"Lámpara de hierba neblinosa","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112028.png","cantidad":18},{"nombre":"Cuerpo divino de Guyun","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114016.png","cantidad":4}]}]'::jsonb, 'Sobre todo para Baizhu. También va bien con Nahida (Arconte Dendro), Neuvillette, Yae Miko, Lisa y Sacarosa (Sucrose).', '[{"id":"gi-baizhu","grupo":"destacado"},{"id":"gi-nahida","grupo":"otros"},{"id":"gi-neuvillette","grupo":"otros"},{"id":"gi-yae-miko","grupo":"otros"},{"id":"gi-lisa","grupo":"otros"},{"id":"gi-sucrose","grupo":"otros"}]'::jsonb),
  ('gi-w-15436', 'genshin-impact', 'Juramento de la Escarcha', 'Covenant of Frost and Snow', '4', 'Arco', 'https://gi.yatta.moe/assets/UI/UI_EquipIcon_Bow_GlintstoneBow.png', 'Un arco largo forjado para cumplir con el propósito de mantener el orden. Su brillo es tan gélido como la más justa e imparcial de las leyes.', null, 510, null, 'DEF', '51,7%', 'Contrapeso de la ley', '["Tras usar su Habilidad Elemental, la Maestría Elemental del portador de esta arma aumenta en 120 pts. durante 12 s.","Tras usar su Habilidad Elemental, la Maestría Elemental del portador de esta arma aumenta en 150 pts. durante 12 s.","Tras usar su Habilidad Elemental, la Maestría Elemental del portador de esta arma aumenta en 180 pts. durante 12 s.","Tras usar su Habilidad Elemental, la Maestría Elemental del portador de esta arma aumenta en 210 pts. durante 12 s.","Tras usar su Habilidad Elemental, la Maestría Elemental del portador de esta arma aumenta en 240 pts. durante 12 s."]'::jsonb, 'Forja: se fabrica en el herrero con su plano', '[{"desde":20,"hasta":40,"creditos":5000,"materiales":[{"nombre":"Semilla quimérica","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112149.png","cantidad":2},{"nombre":"Raíz vacua vital","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112155.png","cantidad":3},{"nombre":"Ascenso del ejército de la Estrella Albina","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114085.png","cantidad":3}]},{"desde":40,"hasta":50,"creditos":15000,"materiales":[{"nombre":"Semilla quimérica","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112149.png","cantidad":8},{"nombre":"Raíz vacua vital","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112155.png","cantidad":12},{"nombre":"Congregación del ejército de la Estrella Albina","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114086.png","cantidad":3}]},{"desde":50,"hasta":60,"creditos":20000,"materiales":[{"nombre":"Célula quimérica simbiótica","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112150.png",