  ('gi-w-15302', 'genshin-impact', 'Juramento del Arquero', 'Sharpshooter''s Oath', '3', 'Arco', 'https://gi.yatta.moe/assets/UI/UI_EquipIcon_Bow_Arjuna.png', 'Este sublime arco perteneció una vez a un maestro arquero. Emite un fuerte olor, por lo que no es apto para la caza.', null, 401, null, 'Daño CRIT', '46,9%', 'Precisión', '["Aumenta en un 24% el daño contra los puntos débiles.","Aumenta en un 30% el daño contra los puntos débiles.","Aumenta en un 36% el daño contra los puntos débiles.","Aumenta en un 42% el daño contra los puntos débiles.","Aumenta en un 48% el daño contra los puntos débiles."]'::jsonb, 'Tirando en el banner permanente · Tirando en los banners de evento', '[{"desde":20,"hasta":40,"creditos":5000,"materiales":[{"nombre":"Condensado de Slime","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112002.png","cantidad":1},{"nombre":"Rama seca de líneas ley","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112020.png","cantidad":2},{"nombre":"Diente de leche de lobo boreal","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114005.png","cantidad":2}]},{"desde":40,"hasta":50,"creditos":10000,"materiales":[{"nombre":"Condensado de Slime","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112002.png","cantidad":5},{"nombre":"Rama seca de líneas ley","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112020.png","cantidad":8},{"nombre":"Diente roto de lobo boreal","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114006.png","cantidad":2}]},{"desde":50,"hasta":60,"creditos":15000,"materiales":[{"nombre":"Babas de Slime","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112003.png","cantidad":4},{"nombre":"Hojas secas de líneas ley","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112021.png","cantidad":4},{"nombre":"Diente roto de lobo boreal","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114006.png","cantidad":4}]},{"desde":60,"hasta":70,"creditos":20000,"materiales":[{"nombre":"Babas de Slime","icono":"https://gi.yatta.moe/assets/U